cd "D:/Java/Obisidian笔记/资料/Redis" && echo "=== 唯一 md 文件 ===" && python3 -c "
import os, hashlib

files = {}
SRC = r'D:\Java\Obisidian笔记\资料\Redis'
for root, dirs, fs in os.walk(SRC):
    if '代码' in root: continue
    for f in fs:
        if not f.endswith('.md'): continue
        fp = os.path.join(root, f)
        with open(fp, encoding='utf-8') as fh:
            h = hashlib.md5(fh.read().encode()).hexdigest()
        if h not in files:
            files[h] = fp
        else:
            print(f'DUPLICATE: {fp}  ==  {files[h]}')

print(f'\nUnique MD files: {len(files)}')
for fp in sorted(files.values()):
    print(f'  {os.path.relpath(fp, SRC)}')
