import os, re

all_mods = ['JavaSE','JavaWeb','MySQL','SSM框架','Redis']
all_notes = {}
all_names = set()

# Collect all real note names
for mod in all_mods:
    for f in os.listdir(mod):
        if f.endswith('.md'):
            name = f.replace('.md','')
            all_names.add(name)
            all_names.add(f'{mod}/{name}')
            all_notes[f'{mod}/{f}'] = ''
            with open(os.path.join(mod,f), encoding='utf-8') as fh:
                all_notes[f'{mod}/{f}'] = fh.read()

print("=== 1. HEADINGS WITH WIKILINKS (creates ghost nodes) ===")
count = 0
for path, content in sorted(all_notes.items()):
    for i, line in enumerate(content.split('\n'), 1):
        s = line.strip()
        if s.startswith('#') and re.search(r'\[\[[^\]]+\]\]', s):
            print(f'  {path}:{i}: {s[:100]}')
            count += 1
print(f'  Total: {count}\n')

print("=== 2. ORPHAN ]] NOT IN WIKILINK (creates ghost nodes) ===")
count = 0
for path, content in sorted(all_notes.items()):
    for i, line in enumerate(content.split('\n'), 1):
        s = line.strip()
        if ']]' in s and '[[' not in s and '![](' not in s:
            print(f'  {path}:{i}: {s[:100]}')
            count += 1
print(f'  Total: {count}\n')

print("=== 3. MISMATCHED BRACKETS ===")
count = 0
for path, content in sorted(all_notes.items()):
    opens = content.count('[[')  
    closes = content.count(']]')
    embeds = content.count('![[')
    if opens - embeds*2 != closes and abs(opens - closes) > 2:
        print(f'  {path}: [[  ={opens}, ]] ={closes}, ![[ ={embeds}')
        count += 1
print(f'  Total: {count}\n')

print("=== 4. TAG-LIKE PATTERNS (show up when showTags=true) ===")
tags = set()
for path, content in sorted(all_notes.items()):
    for m in re.finditer(r'(?<![\[\w])#([a-zA-Z0-9_-]+)', content):
        tags.add(m.group(1))
print(f'  Found {len(tags)} unique: {sorted(tags)[:30]}')
print()

print("=== 5. WIKILINKS TO NON-EXISTENT NOTES ===")
count = 0
for path, content in sorted(all_notes.items()):
    for m in re.finditer(r'(?<!\!)\[\[([^\]|#]+)', content):
        target = m.group(1).strip()
        if target not in all_names:
            found = any(n.endswith(target) or n.endswith(target.split('/')[-1]) for n in all_names)
            if not found:
                print(f'  BROKEN: {path} -> [[{target}]]')
                count += 1
print(f'  Total: {count}\n')

print("=== 6. MISSING FILE:// IMAGE REFS ===")
count = 0
for path, content in sorted(all_notes.items()):
    for ref in re.findall(r'file:///([^)\s]+)', content):
        if not os.path.exists(ref.rstrip('"')):
            print(f'  MISSING: {path} -> {os.path.basename(ref)}')
            count += 1
print(f'  Total: {count}\n')

print("=== 7. NOTES WITHOUT ANY INBOUND LINKS (orphans) ===")
inbound = {n:0 for n in all_names if '/' not in n}
for path, content in sorted(all_notes.items()):
    for m in re.finditer(r'(?<!\!)\[\[([^\]|#]+)', content):
        target = m.group(1).strip().split('/')[-1]
        if target in inbound:
            inbound[target] += 1
for name, cnt in sorted(inbound.items()):
    if cnt == 0:
        print(f'  ORPHAN: {name}')
print(f'  Total with 0 inbound: {sum(1 for v in inbound.values() if v==0)}')

print('\n=== DONE ===')
PYEOF

