from docx import Document
import os, re, zipfile
import xml.etree.ElementTree as ET

docx = 'MySQL/MySQL-进阶篇.docx'
img_dir = 'D:/Java/data/MySQL/进阶篇'
os.makedirs(img_dir, exist_ok=True)

# -- Extract images --
with zipfile.ZipFile(docx) as z:
    rels = ET.fromstring(z.read('word/_rels/document.xml.rels'))
    rid_map = {}
    for rel in rels:
        t = rel.get('Target','')
        if 'image' in rel.get('Type','').lower() or 'media' in t:
            fn = os.path.basename(t)
            rid_map[rel.get('Id')] = fn
            zp = 'word/' + t.replace(chr(92),'/')
            if zp in z.namelist():
                dst = os.path.join(img_dir, fn)
                if not os.path.exists(dst):
                    with open(dst,'wb') as o: o.write(z.read(zp))
    doc_xml = z.read('word/document.xml')
print('Images: ' + str(len(rid_map)))

# -- Parse document --
w = '{http://schemas.openxmlformats.org/wordprocessingml/2006/main}'
wp = '{http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing}'
a = '{http://schemas.openxmlformats.org/drawingml/2006/main}'
rn = '{http://schemas.openxmlformats.org/officeDocument/2006/relationships}'

root = ET.fromstring(doc_xml)
body = root.find(f'{w}body')
out = []

for elem in body:
    tag = elem.tag.split('}')[-1] if '}' in elem.tag else ''

    if tag == 'p':
        # Find images
        imgs = []
        for il in elem.iter(f'{wp}inline'):
            for bl in il.iter(f'{a}blip'):
                rid = bl.get(f'{rn}embed')
                if rid and rid in rid_map:
                    imgs.append(rid_map[rid])
        for an in elem.iter(f'{wp}anchor'):
            for bl in an.iter(f'{a}blip'):
                rid = bl.get(f'{rn}embed')
                if rid and rid in rid_map:
                    imgs.append(rid_map[rid])

        # Get text
        text = ''
        for r in elem.iter(f'{w}r'):
            for t in r.iter(f'{w}t'):
                if t.text:
                    text += t.text

        s = text.strip()

        # Output images
        for img in imgs:
            out.append('![]({IMG})')

        if not s:
            out.append('')
            continue

        # Format headings
        m4 = re.match(r'^\d+\.\d+\.\d+\.\d+\s', s)
        m3 = re.match(r'^\d+\.\d+\.\d+\s', s)
        m2 = re.match(r'^\d+\.\d+\s', s)
        m1 = re.match(r'^\d+\.\s', s)

        if m4 and len(s) < 100:
            out.append('#### ' + s)
        elif m3 and len(s) < 100:
            out.append('#### ' + s)
        elif m2 and len(s) < 100:
            out.append('### ' + s)
        elif m1 and len(s) < 100:
            out.append('## ' + s)
        else:
            out.append(s)

    elif tag == 'tbl':
        # Convert table
        rows = []
        for tr in elem.iter(f'{w}tr'):
            cells = []
            for tc in tr.iter(f'{w}tc'):
                ct = ''
                for t in tc.iter(f'{w}t'):
                    if t.text:
                        ct += t.text
                cells.append(ct.strip().replace('\n',' '))
            rows.append(cells)

        if rows and len(rows) >= 2:
            mc = max(len(r) for r in rows)
            for r in rows:
                while len(r) < mc:
                    r.append('')

            tbl = '| ' + ' | '.join(rows[0]) + ' |\n'
            tbl += '| ' + ' | '.join(['---']*mc) + ' |\n'
            for r in rows[1:]:
                tbl += '| ' + ' | '.join(r) + ' |\n'
            out.append('')
            out.append(tbl.rstrip())
            out.append('')

    else:
        pass  # ignore other elements

content = '\n'.join(out)

# -- Fix image paths --
img_files = set(os.listdir(img_dir))

def fix_one(m):
    path = m.group(1)
    fn = os.path.basename(path.replace(chr(92),'/'))
    stem = fn.rsplit('.',1)[0]
    for af in img_files:
        if af.rsplit('.',1)[0] == stem:
            return '![]({file:///' + img_dir + '/' + af + ')'
    return m.group(0)

content = content.replace('![]({IMG})', 'PLACEHOLDER_IMG')
# Now replace all ![](...) with fixed paths
content = re.sub(r'!\[\]\(([^)]+)\)', fix_one, content)
content = content.replace('{file:///', 'file:///')

# Add file:/// to any remaining D:/ paths
content = re.sub(r'!\[\]\((D:/Java/data/[^)]+)\)',
                 lambda m: '![]({file:///' + m.group(1) + ')', content)
content = content.replace('{file:///', 'file:///')

# -- Clean up --
content = re.sub(r'\n{5,}', '\n\n\n', content)

# -- Add title + footer --
