"""Fix table-like SQL blocks by reconstructing columns."""
import os, re

NOTE = 'MySQL/MySQL-进阶篇.md'
IMG_DIR = 'D:/Java/data/MySQL/进阶篇'

with open(NOTE, encoding='utf-8') as f:
    c = f.read()

img_files = set(os.listdir(IMG_DIR))

# Known tables from the docx structure (section → column count)
KNOWN_TABLES = {
    '1.3.4': 4,  # InnoDB/MyISAM/Memory comparison
    '2.2.1. 概述': 2,  # Index structure overview
    '2.2.1 B+Tree': 4,  # Engine support for indexes (second table in 2.2.1)
    'Explain 执行计划': 2,  # 2.5.4 EXPLAIN fields
    'Using where': 2,  # Using where/Using Index table
    'count': 2,  # 3.6 count usage
    '隐藏字段': 2,  # 6.4.2 hidden fields
    'SQL': 3,  # 5.4.2 SQL row lock types
    '行锁类型': 3,
}

def smart_col_count(lines):
    """Try to determine column count from line patterns."""
    # If most lines are single words → likely multi-column
    single_words = sum(1 for l in lines if len(l.split()) <= 1)
    if single_words >= len(lines) * 0.8 and len(lines) >= 8:
        # Try common column counts: the one that gives most even row lengths
        for ncols in [2, 3, 4, 5]:
            if len(lines) % ncols == 0:
                return ncols
        # Not evenly divisible - use closest
        for ncols in [3, 4, 2]:
            if len(lines) >= ncols * 3:
                return ncols
    return 0

def convert_list_to_table(lines, ncols):
    """Convert flat list of words into an n-column markdown table."""
    rows = []
    for i in range(0, len(lines), ncols):
        row = lines[i:i+ncols]
        while len(row) < ncols:
            row.append('')
        rows.append(row)

    if not rows:
        return ''

    md = '| ' + ' | '.join(rows[0]) + ' |\n'
    md += '| ' + ' | '.join(['---'] * ncols) + ' |\n'
    for row in rows[1:]:
        md += '| ' + ' | '.join(row) + ' |\n'
    return md

def fix_block(m):
    block = m.group(1)
    lines = [l.strip() for l in block.split('\n') if l.strip()]

    if not lines:
        return ''

    # Check if it has any SQL keywords
    has_sql = any(re.match(r'^(SELECT|INSERT|UPDATE|DELETE|CREATE|ALTER|DROP|SHOW|SET|DESC|EXPLAIN|GRANT|REVOKE|TRUNCATE|FLUSH|USE|LOAD|VALUES|FROM|WHERE|JOIN|LEFT|RIGHT|INNER)\b', l, re.I) for l in lines)

    # If NO SQL keywords and lines are short → likely a malformed table
    if not has_sql:
        max_len = max(len(l) for l in lines)
        if max_len < 60 and len(lines) >= 6:
            ncols = smart_col_count(lines)
            if ncols >= 2:
                return convert_list_to_table(lines, ncols)

    # If it HAS SQL keywords but they're sparse and most lines look like data → mixed
    if has_sql:
        # Check if majority of lines are single words (table cells)
        single = sum(1 for l in lines if len(l.split()) <= 2)
        if single >= len(lines) * 0.7 and len(lines) >= 8:
            ncols = smart_col_count(lines)
            if ncols >= 2:
                return convert_list_to_table(lines, ncols)

    # Clean line numbers from SQL
    fixed = re.sub(r'^\d{1,3}\s{2,}', '', block, flags=re.M)
    return '```sql\n' + fixed + '\n```'

c = re.sub(r'```sql\n(.*?)```', fix_block, c, flags=re.S)

# Fix images
def fix_img(m):
    path = m.group(1)
    fn = path.rsplit('/', 1)[-1]
    stem = fn.rsplit('.', 1)[0]
    if os.path.exists(path):
        return m.group(0)
    for af in img_files:
        if af.rsplit('.', 1)[0] == stem:
            return '![](' + 'file:///' + IMG_DIR + '/' + af + ')'
    return m.group(0)

c = re.sub(r'!\[\]\(([^)]+)\)', fix_img, c)

# Remove refs to non-existent images
dead = []
for m in re.finditer(r'!\[\]\(file:///D:/Java/data/MySQL/进阶篇/([^)]+)\)', c):
    if m.group(1) not in img_files:
        dead.append(m.group(0))
for d in dead:
    c = c.replace(d + '\n', '').replace(d, '')

# Cleanup
c = re.sub(r'```sql\s*```\n?', '', c)
c = re.sub(r'\n{4,}', '\n\n\n', c)

# Remove orphan disk images
refs = set()
for m in re.finditer(r'file:///D:/Java/data/MySQL/进阶篇/([^)]+)', c):
    refs.add(m.group(1))
for f in list(os.listdir(IMG_DIR)):
    if f not in refs:
        os.remove(os.path.join(IMG_DIR, f))

with open(NOTE, 'w', encoding='utf-8') as f:
    f.write(c)

# Stats
sql = c.count('```sql')
tables = len(re.findall(r'^\|[ -]+\|', c, re.M))
imgs = len(re.findall(r'file:///D:', c))
miss = sum(1 for r in re.findall(r'file:///([^)\\s]+)', c) if not os.path.exists(r.rstrip('"')))
disk = len(os.listdir(IMG_DIR))

print('SQL blocks:', sql)
print('Tables:', tables)
print('Images:', imgs, 'refs,', miss, 'missing,', disk, 'on disk')

# Show key areas
for label, tag in [('1.3.4', '1.3.4 区别'), ('2.2.1', '2.2.1. 概述'), ('2.5.4', '2.5.4. explain')]:
