    """Convert flat list of words into an n-column markdown table."""
    rows = []
    for i in range(0, len(lines), ncols):
        row = lines[i:i+ncols]
        while len(row) < ncols:
            row.append('')
        rows.append(row)

    if not rows:
        return ''

    md = '| ' + ' | '.join(rows[0]) + ' |\n'
    md += '| ' + ' | '.join(['---'] * ncols) + ' |\n'
