from docx import Document
import os, re, zipfile
import xml.etree.ElementTree as ET

docx_path = 'MySQL/MySQL-进阶篇.docx'
img_dir = 'D:/Java/data/MySQL/进阶篇'
os.makedirs(img_dir, exist_ok=True)

# Extract images
with zipfile.ZipFile(docx_path) as z:
    rels = ET.fromstring(z.read('word/_rels/document.xml.rels'))
    rid_map = {}
    for rel in rels:
        t = rel.get('Target','')
        if 'image' in rel.get('Type','').lower() or 'media' in t:
            fn = os.path.basename(t)
            rid_map[rel.get('Id')] = fn
            zp = 'word/' + t.replace('\\','/')
            if zp in z.namelist():
                d = os.path.join(img_dir, fn)
                with open(d,'wb') as o: o.write(z.read(zp))

# Delete decorative images
for f in list(os.listdir(img_dir)):
    if os.path.getsize(os.path.join(img_dir,f)) < 500:
        os.remove(os.path.join(img_dir,f))

img_files = set(os.listdir(img_dir))
print(f'Images: {len(img_files)}')

# Parse XML directly (NOT via python-docx paragraphs — need tables too)
doc_xml = z.read('word/document.xml')
root = ET.fromstring(doc_xml)
w = '{http://schemas.openxmlformats.org/wordprocessingml/2006/main}'
wp = '{http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing}'
a = '{http://schemas.openxmlformats.org/drawingml/2006/main}'
rn = '{http://schemas.openxmlformats.org/officeDocument/2006/relationships}'

body = root.find(w+'body')
out_lines = []

for elem in body:
    tag = elem.tag.split('}')[-1]

    if tag == 'p':
        # Images
        imgs = []
        for il in elem.iter(wp+'inline'):
            for bl in il.iter(a+'blip'):
                r = bl.get(rn+'embed')
                if r and r in rid_map: imgs.append(rid_map[r])
        for an in elem.iter(wp+'anchor'):
            for bl in an.iter(a+'blip'):
                r = bl.get(rn+'embed')
                if r and r in rid_map: imgs.append(rid_map[r])

        text = ''
        for rn_elem in elem.iter(w+'r'):
            for t in rn_elem.iter(w+'t'):
                if t.text: text += t.text

        s = text.strip()

        # Output images
        for img in imgs:
            stem = img.rsplit('.',1)[0]
            actual = img
            for af in img_files:
                if af.rsplit('.',1)[0] == stem:
                    actual = af; break
            out_lines.append('![](' + img_dir + '/' + actual + ')')

        if not s:
            out_lines.append('')
            continue

        # Heading detection (based on numbering patterns)
        if len(s) < 100:
            if re.match(r'^\d+\.\d+\.\d+\.\d+\s', s):
                out_lines.append('#### ' + s)
