"""Build MySQL-进阶篇.md directly from docx XML."""
import os, re, zipfile
import xml.etree.ElementTree as ET

docx_path = 'MySQL/MySQL-进阶篇.docx'
img_dir = 'D:/Java/data/MySQL/进阶篇'
os.makedirs(img_dir, exist_ok=True)

# ===== Open zip, extract everything, parse XML, close zip =====
with zipfile.ZipFile(docx_path) as z:
    # Extract images
    rels = ET.fromstring(z.read('word/_rels/document.xml.rels'))
    rid_map = {}
    for rel in rels:
        t = rel.get('Target', '')
        if 'image' in rel.get('Type', '').lower() or 'media' in t:
            fn = os.path.basename(t)
            rid_map[rel.get('Id')] = fn
            zp = 'word/' + t.replace(chr(92), '/')
            if zp in z.namelist():
                d = os.path.join(img_dir, fn)
                with open(d, 'wb') as o:
                    o.write(z.read(zp))

    # Parse document XML
    doc_xml = z.read('word/document.xml')
    root = ET.fromstring(doc_xml)

# ===== Delete decorative images =====
for f in list(os.listdir(img_dir)):
    if os.path.getsize(os.path.join(img_dir, f)) < 500:
        os.remove(os.path.join(img_dir, f))

img_files = set(os.listdir(img_dir))
print('Images: ' + str(len(img_files)))

# ===== Process XML body =====
W = '{http://schemas.openxmlformats.org/wordprocessingml/2006/main}'
WP = '{http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing}'
A = '{http://schemas.openxmlformats.org/drawingml/2006/main}'
RN = '{http://schemas.openxmlformats.org/officeDocument/2006/relationships}'

body = root.find(W + 'body')
out = []

for elem in body:
    tag = elem.tag.split('}')[-1]

    if tag == 'p':
        # Find embedded images
        imgs = []
        for il in elem.iter(WP + 'inline'):
            for bl in il.iter(A + 'blip'):
                r = bl.get(RN + 'embed')
                if r and r in rid_map:
                    imgs.append(rid_map[r])
        for an in elem.iter(WP + 'anchor'):
            for bl in an.iter(A + 'blip'):
                r = bl.get(RN + 'embed')
                if r and r in rid_map:
                    imgs.append(rid_map[r])

        # Get text
        text = ''
        for r_e in elem.iter(W + 'r'):
            for t in r_e.iter(W + 't'):
                if t.text:
                    text += t.text
        s = text.strip()

        # Output images
        for img in imgs:
            stem = img.rsplit('.', 1)[0]
            actual = img
            for af in img_files:
                if af.rsplit('.', 1)[0] == stem:
                    actual = af
                    break
            out.append('![](' + img_dir + '/' + actual + ')')

        if not s:
            out.append('')
            continue

        # Heading detection
        if len(s) < 100:
            if re.match(r'^\d+\.\d+\.\d+\.\d+\s', s):
                out.append('#### ' + s)
            elif re.match(r'^\d+\.\d+\.\d+\s', s):
                out.append('#### ' + s)
            elif re.match(r'^\d+\.\d+\s', s):
                out.append('### ' + s)
            elif re.match(r'^\d+\.\s', s):
                out.append('## ' + s)
            else:
                out.append(s)
        else:
            out.append(s)

    elif tag == 'tbl':
        # Convert Word table → markdown table
        rows = []
        for tr in elem.iter(W + 'tr'):
            cells = []
            for tc in tr.iter(W + 'tc'):
                ct = ''
                for t in tc.iter(W + 't'):
                    if t.text:
                        ct += t.text
                cells.append(ct.strip().replace('\n', ' '))
            rows.append(cells)

        if rows and len(rows) >= 2:
            mc = max(len(r) for r in rows)
            for r in rows:
                while len(r) < mc:
                    r.append('')
            tbl = '| ' + ' | '.join(rows[0]) + ' |\n'
            tbl += '| ' + ' | '.join(['---'] * mc) + ' |\n'
            for r in rows[1:]:
                tbl += '| ' + ' | '.join(r) + ' |\n'
            out.append('')
            out.append(tbl.rstrip())
            out.append('')

content = '\n'.join(out)

# ===== Add file:/// prefix =====
prefix = 'file:///D:/Java/data/MySQL/进阶篇/'
content = content.replace('![](' + img_dir + '/', '![](' + prefix)

# Fix remaining image refs
def fix_img(m):
    path = m.group(1)
    fn = path.rsplit('/', 1)[-1]
    stem = fn.rsplit('.', 1)[0]
    for af in img_files:
        if af.rsplit('.', 1)[0] == stem:
            return '![](' + prefix + af + ')'
    return ''

content = re.sub(r'!\[\]\(D:/Java/data/MySQL/进阶篇/([^)]+)\)', fix_img, content)

# Remove dead refs and orphan images
refs = set()
for m in re.finditer(r'file:///D:/Java/data/MySQL/进阶篇/([^)]+)', content):
    refs.add(m.group(1))
for f in list(os.listdir(img_dir)):
    if f not in refs:
        os.remove(os.path.join(img_dir, f))

# ===== Cleanup =====
content = re.sub(r'\n{5,}', '\n\n\n', content)

# Title + footer
content = '# MySQL 进阶篇\n\n' + content
content += '\n\n---\n\n> \U0001f4ce **相关笔记**：[[MySQL-基础篇]] · [[MySQL-运维篇]] · [[MySQL 索引]] · [[JavaWeb/02-数据库与持久层|JavaWeb 持久层]]\n'

