imgs = len(re.findall(r'file:///D:', content))
miss = sum(1 for r in re.findall(r'file:///([^)\\s]+)', content) if not os.path.exists(r.rstrip('"')))
disk = len(os.listdir(img_dir))
print('Imgs=' + str(imgs) + ' Miss=' + str(miss) + ' Disk=' + str(disk))

for tag in ['3.2 主键优化', '4.2 存储过程', '2.2.1 概述', '5.4.2 行锁', '6.4.2 隐藏字段']:
