import os, re

mods = ['JavaSE', 'JavaWeb', 'MySQL', 'SSM框架', 'Redis']

print("=== 拆分建议详情 ===\n")

for mod in mods:
    for fname in sorted(os.listdir(mod)):
        if '索引' in fname: continue
        fpath = os.path.join(mod, fname)
        with open(fpath, encoding='utf-8') as f:
            c = f.read()

        kb = len(c.encode('utf-8')) / 1024
        if kb < 50: continue  # skip small notes

        print(f"## {mod}/{fname} ({kb:.0f}KB)")

        # Find section breaks (---) and extract what follows
        sections = re.split(r'\n---\n', c)

        # Find first heading after each break to label sections
        labels = []
        for i, sec in enumerate(sections):
            h = re.findall(r'^#{1,3}\s+(.+)$', sec.strip(), re.M)
            if h:
                labels.append(h[0][:60])
            else:
                # Try to find first meaningful text
                lines = [l.strip() for l in sec.strip().split('\n') if l.strip() and not l.startswith('![](') and not l.startswith('```')]
                if lines:
                    labels.append(lines[0][:60])
                else:
                    labels.append(f"(section {i+1})")

        # Only show real section breaks (--- followed by content)
        real_splits = re.findall(r'\n---\n(#{1,3}\s+.+)', c)

        if len(sections) <= 1 and kb < 100:
            # Single section, could split by chapter headings
            chapters = re.findall(r'^##\s+\d+[\.\s].+$', c, re.M)
            # Also numbered headings at start of lines
            numbered = re.findall(r'^(?!#)(\d+)\.\s+.+$', c, re.M)

            if chapters:
                print(f"  按章节标题拆 ({len(chapters)}章):")
                for ch in chapters[:8]:
                    print(f"    → {ch.replace('## ','')[:70]}")
                if len(chapters) > 8: print(f"    ... +{len(chapters)-8}")
            elif numbered:
                print(f"  按编号段落 ({len(numbered)}段)")
            else:
                print(f"  无明确章节，建议整个保留或按H2标题拆")
                h2s = re.findall(r'^##\s+(.+)$', c, re.M)[:6]
                for h in h2s:
                    print(f"    H2: {h[:70]}")
        elif len(sections) > 1:
            print(f"  按 --- 分隔符拆 ({len(sections)}节):")
            for i, label in enumerate(labels[:8]):
                print(f"    [{i}] {label}")
            if len(labels) > 8: print(f"    ... +{len(labels)-8}")

        print()
