for mod_dir in sorted(os.listdir(DATA_BASE)):
    dp = os.path.join(DATA_BASE, mod_dir)
    if not os.path.isdir(dp): continue
    for sub in sorted(os.listdir(dp)):
        sp = os.path.join(dp, sub)
        cnt = len(os.listdir(sp)) if os.path.isdir(sp) else 0
        print('  ' + mod_dir + '/' + sub + ': ' + str(cnt) + ' files')

# 4. Vault structure (folders only)
print("\n=== 4. Vault结构 ===")
for mod in MODS:
    print('\n' + mod + '/')
    for item in sorted(os.listdir(mod)):
        ip = os.path.join(mod, item)
        if os.path.isdir(ip):
            n = len([f for f in os.listdir(ip) if f.endswith('.md')])
            print('  [' + item + '] (' + str(n) + '篇)')
        elif item.endswith('.md'):
            kb = os.path.getsize(ip) // 1024
            print('  ' + item + ' (' + str(kb) + 'KB)')

